import type { ModelSlotsView, Slot, SlotModelView } from "@shared/modelSlots";
import { offeringKey, SLOTS } from "@shared/modelSlots";
import type { RoutingSettings } from "@shared/quota";
import { QUOTA_TO_PI_PROVIDER } from "@shared/quota";
import { useEffect, useState } from "react";
import { Button, RowMenu, type RowMenuItem, SlotBadge } from "../design";

/**
 * "Which of my models may Firstmate use, and as what." Slot-first: four
 * groups plus Off, provider on every row. Off means in no slot. A pin (✱)
 * always wins, including a premium-slot model the ladder never reaches.
 *
 * Since the Instruments relayout the section is a collapsed disclosure: the
 * header line carries the whole story ("premium 2 · high 4 · 31 off · 1
 * pinned ✱") and the board opens on demand, or from a row's "Model slots".
 */

const PI_TO_QUOTA: Record<string, string> = Object.fromEntries(
  Object.entries(QUOTA_TO_PI_PROVIDER).map(([quotaId, piId]) => [piId, quotaId]),
);

const CARD_MAX_ROWS_HEIGHT = 232;

const LABEL_STYLE = {
  fontSize: "var(--text-xs)",
  fontWeight: 500,
  letterSpacing: "var(--tracking-label)",
  textTransform: "uppercase",
  color: "var(--fg-3)",
} as const;

const SLOT_HINT: Record<Slot, string> = {
  premium: "Only when you name it ✱",
  high: "Design, debugging, the hard parts",
  medium: "Everyday work",
  low: "Quick fixes, triage",
};

const EMPTY_HINT: Record<Slot, string> = {
  premium: "nothing here - name a model to use this slot",
  high: "nothing here - work asked for high runs on medium",
  medium: "nothing here - work asked for medium runs on high",
  low: "nothing here - work asked for low runs on medium",
};

const OFF_COLLAPSE_AT = 8;

const chevron = (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="m6 9 6 6 6-6" />
  </svg>
);

export function ModelsSection({
  slots,
  routing,
  open,
  onToggle,
  focusAccountId,
  onFocused,
  onSaveRouting,
  onSetSlot,
  onResetSlots,
}: {
  slots: ModelSlotsView | null;
  routing: RoutingSettings | null;
  open: boolean;
  onToggle: () => void;
  /** Kept so a kebab "Model slots" can open the board; no per-account card. */
  focusAccountId: string | null;
  onFocused: () => void;
  onSaveRouting: (settings: RoutingSettings) => void;
  onSetSlot: (key: string, slot: Slot | null) => void;
  onResetSlots: () => void;
}) {
  const models = slots?.models ?? [];
  const [resetArmed, setResetArmed] = useState(false);
  const [offOpen, setOffOpen] = useState(false);

  useEffect(() => {
    if (!open || !focusAccountId) return;
    document.getElementById("fm-subs-models-panel")?.scrollIntoView({ block: "nearest" });
    onFocused();
  }, [open, focusAccountId, onFocused]);

  if (models.length === 0) return null;

  const pinRefFor = (model: { provider: string; id: string }) => ({
    provider: PI_TO_QUOTA[model.provider] ?? model.provider,
    id: model.id,
  });

  const isPinned = (model: { provider: string; id: string }): boolean => {
    const ref = pinRefFor(model);
    return routing?.pins.some((pin) => pin.provider === ref.provider && pin.id === ref.id) ?? false;
  };

  const togglePin = (model: { provider: string; id: string }) => {
    if (!routing) return;
    const ref = pinRefFor(model);
    onSaveRouting({
      ...routing,
      pins: isPinned(model)
        ? routing.pins.filter((pin) => !(pin.provider === ref.provider && pin.id === ref.id))
        : [...routing.pins, ref],
    });
  };

  const grouped: Record<Slot | "off", SlotModelView[]> = {
    premium: [],
    high: [],
    medium: [],
    low: [],
    off: [],
  };
  for (const model of models) {
    grouped[model.slot ?? "off"].push(model);
  }

  const pinnedCount = models.filter(isPinned).length;
  const newCount = models.filter((model) => model.isNew).length;
  const summary = slots?.usingDefaults
    ? "nothing slotted - using the starter map"
    : [
        ...SLOTS.map((slot) => (grouped[slot].length > 0 ? `${slot} ${grouped[slot].length}` : "")),
        grouped.off.length > 0 ? `${grouped.off.length} off` : "",
        pinnedCount ? `${pinnedCount} pinned ✱` : "",
        newCount ? `${newCount} new` : "",
      ]
        .filter(Boolean)
        .join(" · ");

  const renderRow = (model: SlotModelView) => {
    const key = offeringKey(model);
    const pinned = isPinned(model);
    const verb = model.slot ? "Move to" : "Put in";
    const items: RowMenuItem[] = [
      ...SLOTS.map((slot) => ({
        id: `slot-${slot}`,
        label: `${verb} ${slot}`,
        ...(model.slot === slot
          ? { trailing: <span style={{ color: "var(--accent)" }}>·</span> }
          : {}),
        onSelect: () => onSetSlot(key, slot),
      })),
      { separator: true as const },
      {
        id: "pin",
        label: pinned ? "Unpin" : "Pin ✱",
        onSelect: () => togglePin(model),
      },
      ...(model.slot
        ? [
            { separator: true as const },
            {
              id: "off",
              label: "Turn off",
              onSelect: () => onSetSlot(key, null),
            },
          ]
        : []),
    ];
    return (
      <div
        key={key}
        data-model-row={key}
        style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}
      >
        <span
          style={{
            ...LABEL_STYLE,
            textTransform: "none",
            letterSpacing: 0,
            flexShrink: 0,
            width: 64,
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
          }}
        >
          {model.providerLabel}
        </span>
        <button
          type="button"
          onClick={() => togglePin(model)}
          title={pinned ? "Unpin model" : "Pin model"}
          style={{
            background: "transparent",
            border: "none",
            padding: 0,
            cursor: "pointer",
            flex: 1,
            minWidth: 0,
            fontFamily: "var(--font-mono)",
            fontSize: "var(--text-sm)",
            color: pinned ? "var(--accent)" : model.slot ? "var(--fg-2)" : "var(--fg-3)",
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
            textAlign: "left",
          }}
        >
          {model.label}
          {pinned ? " ✱" : ""}
        </button>
        {model.isNew && (
          <span
            title="New here - it stays off until you place it in a slot."
            style={{
              flexShrink: 0,
              fontSize: "var(--text-xs)",
              letterSpacing: "var(--tracking-label)",
              textTransform: "uppercase",
              color: "var(--accent)",
            }}
          >
            new
          </span>
        )}
        <RowMenu label={`${model.label} actions`} items={items} size={24} />
      </div>
    );
  };

  const slotCard = (slot: Slot) => (
    <div
      key={slot}
      data-slot-group={slot}
      style={{
        background: "var(--bg-2)",
        border: "1px solid var(--line-1)",
        borderRadius: "var(--radius-m)",
        padding: "10px 12px",
        display: "flex",
        flexDirection: "column",
        gap: 8,
        minWidth: 0,
      }}
    >
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, minWidth: 0 }}>
        <SlotBadge slot={slot} />
        <span
          style={{
            fontSize: "var(--text-xs)",
            color: "var(--fg-3)",
            minWidth: 0,
          }}
        >
          {SLOT_HINT[slot]}
        </span>
      </div>
      {grouped[slot].length === 0 ? (
        <div style={{ fontSize: "var(--text-sm)", color: "var(--fg-3)" }}>{EMPTY_HINT[slot]}</div>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 8,
            maxHeight: CARD_MAX_ROWS_HEIGHT,
            overflowY: "auto",
          }}
        >
          {grouped[slot].map(renderRow)}
        </div>
      )}
    </div>
  );

  const offRows = grouped.off;
  const offCollapsed = offRows.length > OFF_COLLAPSE_AT && !offOpen;

  return (
    <section aria-label="Models" className="fm-subs-disclose">
      <button
        type="button"
        className="fm-subs-disclose-head"
        aria-expanded={open}
        aria-controls="fm-subs-models-panel"
        onClick={onToggle}
      >
        <span style={{ fontSize: "var(--text-base)", fontWeight: 500, color: "var(--fg-1)" }}>
          Models
        </span>
        <span
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: "var(--text-xs)",
            color: "var(--fg-3)",
            minWidth: 0,
            overflowWrap: "anywhere",
          }}
        >
          {summary}
        </span>
        <span className="fm-subs-chevron">{chevron}</span>
      </button>
      {open && (
        <div
          id="fm-subs-models-panel"
          className="fm-subs-disclose-body"
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 12,
            padding: "0 18px 16px",
          }}
        >
          {SLOTS.map(slotCard)}
          <div
            data-slot-group="off"
            style={{
              background: "var(--bg-2)",
              border: "1px solid var(--line-1)",
              borderRadius: "var(--radius-m)",
              padding: "10px 12px",
              display: "flex",
              flexDirection: "column",
              gap: 8,
              minWidth: 0,
            }}
          >
            <div style={{ ...LABEL_STYLE }}>Off</div>
            {offRows.length === 0 ? (
              <div style={{ fontSize: "var(--text-sm)", color: "var(--fg-3)" }}>
                every model sits in a slot
              </div>
            ) : offCollapsed ? (
              <button
                type="button"
                onClick={() => setOffOpen(true)}
                style={{
                  background: "transparent",
                  border: "none",
                  padding: 0,
                  cursor: "pointer",
                  textAlign: "left",
                  fontFamily: "var(--font-mono)",
                  fontSize: "var(--text-sm)",
                  color: "var(--fg-3)",
                }}
              >
                {offRows.length} off
              </button>
            ) : (
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 8,
                  maxHeight: CARD_MAX_ROWS_HEIGHT,
                  overflowY: "auto",
                }}
              >
                {offRows.map(renderRow)}
              </div>
            )}
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <Button
              variant={resetArmed ? "danger" : "ghost"}
              size="sm"
              onClick={() => {
                if (!resetArmed) {
                  setResetArmed(true);
                  return;
                }
                onResetSlots();
                setResetArmed(false);
              }}
            >
              {resetArmed ? "Confirm reset" : "Reset to defaults"}
            </Button>
            {resetArmed && (
              <span style={{ fontSize: "var(--text-xs)", color: "var(--fg-3)" }}>
                Pins are untouched.
              </span>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

import { z } from "zod";
import { catalogEntry } from "./providers";

/**
 * User-assigned intelligence slots (settled 2026-09-10). The catalog no
 * longer stamps a per-model tier; the user places each offering in at most
 * one of these four, and off means in no slot. The names ARE the contract:
 * spawn_crewmate.difficulty, bucket: gate refs, consult/supervision grains,
 * and routing_decisions.bucket all speak them.
 */
export const slotSchema = z.enum(["premium", "high", "medium", "low"]);
export type Slot = z.infer<typeof slotSchema>;
export const SLOTS: ReadonlyArray<Slot> = ["premium", "high", "medium", "low"];

/** The slot automatic selection may never reach for. */
export const PREMIUM_SLOT = "premium" as const;

/**
 * The slots automatic selection operates over, strongest first. Every slot
 * walk in the app reads this rather than repeating a literal, so the
 * premium exclusion cannot drift out of one of them.
 */
export const AUTO_ROUTABLE_SLOTS: ReadonlyArray<Slot> = ["high", "medium", "low"];

/** True when a slot may be chosen without the user naming the model. */
export function isAutoRoutableSlot(slot: Slot): boolean {
  return slot !== PREMIUM_SLOT;
}

/**
 * An offering: one model as one provider serves it. Decision C stands -
 * github-copilot/gpt-5.6-sol and openai-codex/gpt-5.6-sol are two offerings.
 */
export function offeringKey(model: { provider: string; id: string }): string {
  return `${model.provider}/${model.id}`;
}

export function parseOfferingKey(key: string): { provider: string; id: string } {
  const slash = key.indexOf("/");
  if (slash <= 0 || slash === key.length - 1) return { provider: "", id: key };
  return { provider: key.slice(0, slash), id: key.slice(slash + 1) };
}

export const modelSlotsStateSchema = z.object({
  version: z.literal(1),
  /** offering → slot. A key absent here is OFF: never auto-picked, still pinnable. */
  assignments: z.record(z.string(), slotSchema),
  /** every offering this install has ever been offered. Seeding only touches keys absent here. */
  seen: z.array(z.string()),
});
export type ModelSlotsState = z.infer<typeof modelSlotsStateSchema>;

export const EMPTY_MODEL_SLOTS: ModelSlotsState = {
  version: 1,
  assignments: {},
  seen: [],
};

/**
 * The settled starter map (captain, 2026-09-10). Today's default-approved
 * entries with their slot attached, minus Copilot claude-fable-5 (off:
 * superseded by 5.1), plus the captain's anchors. A row for an id the
 * provider never ships is inert: seeding only runs over offerings in the
 * pool. claude-fable-5-1 is guarded here until CLAUDE_MODELS names it.
 */
export const STARTER_SLOTS: Readonly<Record<string, Readonly<Record<string, Slot>>>> = {
  "openai-codex": {
    "gpt-6-astra": "premium",
    "gpt-5.6-sol": "high",
    "gpt-5.6-terra": "medium",
    "gpt-5.6-luna": "low",
  },
  "github-copilot": {
    "claude-fable-5.1": "premium",
    "gpt-6-astra": "premium",
    "claude-opus-5": "high",
    "gpt-5.6-sol": "high",
    "claude-sonnet-5": "medium",
    "gpt-5.6-luna": "low",
  },
  xai: { "grok-4.6": "high" },
  "kimi-coding": { k3: "high" },
  "anthropic-claude": {
    "claude-opus-5": "high",
    "claude-sonnet-5": "medium",
    "claude-haiku-4-5": "low",
    // Guarded: add to CLAUDE_MODELS when it ships. Inert until then.
    "claude-fable-5-1": "premium",
  },
  cursor: {
    "cursor-grok-4.6-high": "high",
    auto: "medium",
  },
};

/** The starter slot for one offering, if the map names it. */
export function starterSlot(providerId: string, id: string): Slot | undefined {
  return STARTER_SLOTS[providerId]?.[id];
}

/** The starter-map keys for one provider, as offering keys. */
export function starterKeys(providerId: string): string[] {
  return Object.keys(STARTER_SLOTS[providerId] ?? {}).map((id) => `${providerId}/${id}`);
}

/** Every starter-map key across providers. */
export function allStarterKeys(): string[] {
  return Object.keys(STARTER_SLOTS).flatMap((providerId) => starterKeys(providerId));
}

/** One model row on the slot-first Settings board. */
export const slotModelViewSchema = z.object({
  /** Pi provider id serving this model (never the quota id). */
  provider: z.string(),
  providerLabel: z.string(),
  id: z.string(),
  label: z.string(),
  /** null = off (in no slot). */
  slot: slotSchema.nullable(),
