import type { CatalogModelView, ModelsCatalogView, QuotaProviderView } from "@shared/quota";
import { QUOTA_TO_PI_PROVIDER } from "@shared/quota";
import { providerScopes, type ScopeSignals } from "@shared/quotaSignals";
import type { QuotaCatalogModel } from "./auth";

const PI_TO_QUOTA: Record<string, string> = Object.fromEntries(
  Object.entries(QUOTA_TO_PI_PROVIDER).map(([quotaId, piId]) => [piId, quotaId]),
);

type EffectiveView = {
  effectivePercentRemaining?: number;
  paceStatus?: CatalogModelView["paceStatus"];
  spendPriority?: number;
};

/**
 * Does a model-scoped quota window (a "model:<slug>" scope) apply to this
 * catalog model? Conservative on purpose: the slug's normalized tokens must
 * appear contiguously inside the model id's ("fable" in claude-fable-5;
 * "opus" in claude-opus-4-5). A vendor codename that matches nothing falls
 * back to the account-wide scope rather than a guessed narrowing.
 */
export function scopeAppliesToModel(scope: string, modelId: string): boolean {
  const slug = scope.replace(/^model:/, "");
  const tokens = (value: string) =>
    value.toLowerCase().replace(/[._:]/g, "-").split("-").filter(Boolean);
  const slugTokens = tokens(slug);
  const idTokens = tokens(modelId);
  if (slugTokens.length === 0) return false;
  outer: for (let start = 0; start <= idTokens.length - slugTokens.length; start++) {
    for (let offset = 0; offset < slugTokens.length; offset++) {
      if (idTokens[start + offset] !== slugTokens[offset]) continue outer;
    }
    return true;
  }
  return false;
}

/**
 * One account row's effective view for a model: the account-wide scope
 * (windows that jointly bound every model), narrowed by a model-scoped
 * window when one names this model. Model windows never drag the
 * account-wide minimum down for OTHER models - that is the scope rule
 * (quota-axi parity), and a provider with unknown window relationships
 * (Copilot) reports no combined number at all instead of a fabricated min.
 */
export function effectiveFromProvider(
  provider: QuotaProviderView | undefined,
  nowMs: number,
  modelId?: string,
): EffectiveView {
  if (provider?.status !== "ok" || provider.stale) return {};
  const view = providerScopes(provider, nowMs);
  let scope: ScopeSignals | undefined = view.allModels;
  if (modelId) {
    const match = view.scopes.find(
      (candidate) =>
        candidate.scope.startsWith("model:") && scopeAppliesToModel(candidate.scope, modelId),
    );
    if (match) scope = match;
  }
  if (!scope) return {};
  // The pace label keeps the pre-existing display ladder over the scope's
  // own windows (ahead - the conserve signal - outranks the rest).
  const scopeWindowIds = new Set(scope.boundedBy);
  const paces = provider.windows
    .filter((window) => scopeWindowIds.has(window.id))
    .map((window) => window.pace)
    .filter((value): value is NonNullable<typeof value> => Boolean(value));
  const paceStatus = paces.includes("ahead")
    ? "ahead"
    : paces.includes("behind")
      ? "behind"
      : paces.includes("on_pace")
        ? "on_pace"
        : paces.includes("unknown")
          ? "unknown"
          : undefined;
  return {
    ...(scope.effectivePercentRemaining !== undefined
      ? { effectivePercentRemaining: scope.effectivePercentRemaining }
      : {}),
    ...(paceStatus ? { paceStatus } : {}),
    ...(scope.spendPriority !== undefined ? { spendPriority: scope.spendPriority } : {}),
  };
}

/**
 * With N accounts per provider (broker phase 2), a model's catalog signals
 * are the BEST account's - the routing engine picks the model, then the
 * account-selection step picks which account serves it. Best is the highest
 * spend priority when any account has one (that is the account with paid
 * allowance on track to expire unused), highest effective remaining
 * otherwise; an unmeasurable signal is never ranked as zero.
 */
function effectiveAcrossAccounts(
  rows: QuotaProviderView[],
  nowMs: number,
  modelId: string,
): EffectiveView {
  let best: EffectiveView = {};
  for (const row of rows) {
    const effective = effectiveFromProvider(row, nowMs, modelId);
    if (effective.effectivePercentRemaining === undefined) continue;
    const bestPriority = best.spendPriority;
    const priority = effective.spendPriority;
    const wins =
      best.effectivePercentRemaining === undefined ||
      (priority !== undefined && bestPriority === undefined) ||
      (priority !== undefined && bestPriority !== undefined && priority > bestPriority) ||
      (priority === undefined &&
        bestPriority === undefined &&
        effective.effectivePercentRemaining > best.effectivePercentRemaining);
    if (wins) best = effective;
  }
  if (best.effectivePercentRemaining !== undefined) return best;
  // No measurable account: fall back to the first row's pace-only view.
  return rows.length > 0 ? effectiveFromProvider(rows[0], nowMs, modelId) : {};
}

function runwayRank(model: CatalogModelView): number {
  if (typeof model.effectivePercentRemaining === "number") return model.effectivePercentRemaining;
  return -1;
}

export function buildModelsCatalog(
  models: QuotaCatalogModel[],
  providers: QuotaProviderView[],
  generatedAt: string,
  nowMs?: number,
): ModelsCatalogView {
  const at =
    nowMs ?? (Number.isFinite(Date.parse(generatedAt)) ? Date.parse(generatedAt) : Date.now());
  const byQuotaId = new Map<string, QuotaProviderView[]>();
  for (const provider of providers) {
    const rows = byQuotaId.get(provider.provider) ?? [];
    rows.push(provider);
    byQuotaId.set(provider.provider, rows);
  }
  const catalog: CatalogModelView[] = models.flatMap((model) => {
    const quotaId = PI_TO_QUOTA[model.provider];
    if (!quotaId) return [];
    const effective = effectiveAcrossAccounts(byQuotaId.get(quotaId) ?? [], at, model.id);
    return [
      {
        provider: quotaId,
        id: model.id,
        label: model.name,
        ...effective,
      },
    ];
  });
  // Spend-priority order (quota-axi ranking semantics): the scope whose paid
  // allowance is most on track to expire unused comes first. Models without
  // a measurable signal keep runway order among themselves - unknown is not
  // zero, and headroom is still real evidence.
  catalog.sort((a, b) => {
    const aKnown = typeof a.spendPriority === "number";
    const bKnown = typeof b.spendPriority === "number";
    if (aKnown !== bKnown) return aKnown ? -1 : 1;
    if (aKnown && bKnown && a.spendPriority !== b.spendPriority) {
      return (b.spendPriority as number) - (a.spendPriority as number);
    }
    const rank = runwayRank(b) - runwayRank(a);
    if (rank !== 0) return rank;
    return `${a.provider}/${a.id}`.localeCompare(`${b.provider}/${b.id}`);
  });
  return { generatedAt, models: catalog };
}

export const KEYCHAIN_VALUE_FAILURE_DETAIL: Record<KeychainValueFailure, string> = {
  keychain_access_denied: "macOS didn't allow reading usage. Retry to try again.",
  keychain_prompt_timeout: "The permission prompt timed out. Retry to try again.",
  keychain_unavailable: "Usage couldn't be read from this account's store. Retry to try again.",
  keychain_unreadable: "Usage couldn't be read from this account's store. Retry to try again.",
  keychain_no_interactive_session:
    "FM3000 can't reach the macOS Keychain from the session it was launched in. Relaunch it from the Dock, or allow the read once while it is running there.",
};

export function isKeychainValueFailure(reason: string | undefined): reason is KeychainValueFailure {
  return reason !== undefined && (KEYCHAIN_VALUE_FAILURES as readonly string[]).includes(reason);
}

export const quotaSnapshotViewSchema = z.object({
  generatedAt: z.string(),
  fetchedAt: z.number(),
  providers: z.array(quotaProviderViewSchema),
});
export type QuotaSnapshotView = z.infer<typeof quotaSnapshotViewSchema>;

/**
 * Slot names still ride routing_decisions.bucket, difficulty, and quota-gate
 * refs. The catalog itself no longer stamps a per-model intelligence tier;
 * the user's slot record supplies that (src/shared/modelSlots.ts).
 */
export const catalogModelViewSchema = z.object({
  /** Quota provider id. */
  provider: z.string(),
  id: z.string(),
  label: z.string(),
  effectivePercentRemaining: z.number().optional(),
  paceStatus: z.enum(["ahead", "on_pace", "behind", "unknown"]).optional(),
  /**
   * The per-scope selection signal, quota-axi semantics: positive means paid
   * allowance is on track to reach reset unused (spend here first), zero is
   * exact utilization, negative is overdrawn against the reset clock.
   * Absent means unmeasurable - never rendered or ranked as zero.
   */
  spendPriority: z.number().optional(),
});
export type CatalogModelView = z.infer<typeof catalogModelViewSchema>;

/**
 * Models in spend-priority order for routing (highest reclaimable allowance
 * first, quota-axi ranking semantics), with remaining-quota runway order as
 * the fallback among models whose signal is unmeasurable.
 */
export const modelsCatalogViewSchema = z.object({
  generatedAt: z.string(),
  models: z.array(catalogModelViewSchema),
});
export type ModelsCatalogView = z.infer<typeof modelsCatalogViewSchema>;

export const modelPinSchema = z.object({ provider: z.string(), id: z.string() });
export type ModelPin = z.infer<typeof modelPinSchema>;

/** A Pi provider/model pair, as Pi resolves it (not quota provider ids). */
