/** The section is a collapsed disclosure since the Instruments relayout. */
async function openModels(page: Page) {
  const models = page.getByRole("region", { name: "Models" });
  await expect(models).toBeVisible({ timeout: 20_000 });
  const head = models.getByRole("button", { name: /^Models/ });
  if ((await head.getAttribute("aria-expanded")) !== "true") await head.click();
  await expect(head).toHaveAttribute("aria-expanded", "true");
  return models;
}

test("the models section lists the connected subscriptions only", async () => {
  const { page } = launched;
  const models = await openModels(page);

  // The two connected subscriptions, with rows from the real catalog.
  await expect(models.getByText("Claude", { exact: true }).first()).toBeVisible();
  await expect(models.getByText("Cursor", { exact: true }).first()).toBeVisible();
  await expect(models.getByRole("button", { name: "Claude Opus 5", exact: true })).toBeVisible();
  await expect(
    models
      .locator('[data-slot-group="off"]')
      .getByRole("button", { name: "Composer 2.5", exact: true }),
  ).toBeVisible();

  // Providers with no usable account contribute nothing, though the
  // provider-wide catalog behind the section still carries them.
  for (const label of ["Codex", "Copilot", "Grok", "Kimi"]) {
    await expect(models.getByText(label, { exact: true })).toHaveCount(0);
  }
  // A Pi model id that only the un-gated global catalog could have supplied.
  await expect(models.getByText("GPT-5.5", { exact: true })).toHaveCount(0);
  // The list above is unaffected: the paused Grok account still has its
  // row (dimmed, "paused"), and the foot offers another.
  await expect(page.locator(`[data-account-row="${GROK_DISABLED}"]`)).toHaveAttribute(
    "data-paused",
    "true",
  );
  await expect(page.getByRole("button", { name: "Add another Grok account" })).toBeVisible();

