/**
 * The ⋯ at the end of a list row (design skill RowMenu): every action the
 * row offers, out of the glance path. Anchored bottom-right; closes on
 * Escape, an outside click, or a pick. Arrow keys walk the items and focus
 * returns to the kebab on close, so the menu is a keyboard citizen.
 */
export function RowMenu({ label, items, size = 28, style }: RowMenuProps) {
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLSpanElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (event: PointerEvent) => {
      if (wrap.current && !wrap.current.contains(event.target as Node)) setOpen(false);
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        // The menu owns this Escape: the shell's own listener (which would
        // close Settings) must not also see it.
        event.stopPropagation();
        setOpen(false);
        trigger.current?.focus();
        return;
      }
      if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
      const focusable = [
        ...(menu.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? []),
      ];
      if (focusable.length === 0) return;
      event.preventDefault();
      const index = focusable.indexOf(document.activeElement as HTMLButtonElement);
      const step = event.key === "ArrowDown" ? 1 : -1;
      const next = focusable[(index + step + focusable.length) % focusable.length];
      next?.focus();
    };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    menu.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus();
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <span
      ref={wrap}
      style={{ position: "relative", flexShrink: 0, display: "inline-flex", ...style }}
    >
      <IconButton
        ref={trigger}
        label={label}
        size={size}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        {kebab}
      </IconButton>
      {open && (
        <div
          ref={menu}
          role="menu"
          aria-label={label}
          style={{
            position: "absolute",
            right: 0,
            top: size + 4,
            zIndex: 4,
            minWidth: 180,
            background: "var(--bg-2)",
            border: "1px solid var(--line-2)",
            borderRadius: "var(--radius-m)",
            boxShadow: "var(--shadow-2)",
            padding: 6,
            display: "flex",
            flexDirection: "column",
            gap: 2,
          }}
        >
          {items.map((item, index) =>
            "separator" in item ? (
              <hr
                // biome-ignore lint/suspicious/noArrayIndexKey: separators have no identity
                key={`separator-${index}`}
                style={{
                  height: 1,
                  border: 0,
                  background: "var(--line-1)",
                  margin: "4px 2px",
                }}
              />
            ) : (
              <MenuItem
                key={item.id}
                item={item}
                onPick={() => {
                  setOpen(false);
                  trigger.current?.focus();
                  item.onSelect?.();
                }}
              />
            ),
          )}
        </div>
      )}
    </span>
  );
}

function MenuItem({
  item,
  onPick,
}: {
  item: Exclude<RowMenuItem, { separator: true }>;
  onPick: () => void;
}) {
  const [hover, setHover] = useState(false);
  return (
    <button
      type="button"
      role="menuitem"
      onClick={onPick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        background: hover ? "var(--bg-3)" : "transparent",
        border: 0,
        textAlign: "left",
        padding: "7px 10px",
        borderRadius: "var(--radius-s)",
        fontFamily: "var(--font-ui)",
        fontSize: "var(--text-sm)",
        color: item.tone === "danger" ? "var(--danger)" : "var(--fg-1)",
        cursor: "pointer",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        gap: 12,
        whiteSpace: "nowrap",
      }}
    >
      <span>{item.label}</span>
      {item.trailing}
    </button>
  );
}

import type React from "react";
import { useState } from "react";

export type ButtonVariant = "primary" | "secondary" | "ghost" | "danger";
export type ButtonSize = "sm" | "md" | "lg";

export type ButtonProps = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  disabled?: boolean;
  pending?: boolean;
  pendingLabel?: string;
  icon?: React.ReactNode;
  children?: React.ReactNode;
  style?: React.CSSProperties;
} & Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "style">;

const base: React.CSSProperties = {
  fontFamily: "var(--font-ui)",
  fontSize: "var(--text-base)",
  fontWeight: 500,
  borderRadius: "var(--radius-m)",
  cursor: "pointer",
  display: "inline-flex",
  alignItems: "center",
  gap: 8,
  border: "1px solid transparent",
  transition:
    "background var(--dur-fast) var(--ease-out),border-color var(--dur-fast) var(--ease-out),opacity var(--dur-fast) var(--ease-out)",
  lineHeight: 1,
  // A button label never wraps or gets crushed by a cramped flex row - the
  // row's flexible content gives way instead (design skill Button rule).
  whiteSpace: "nowrap",
  flexShrink: 0,
};

const variants: Record<ButtonVariant, React.CSSProperties> = {
  primary: { background: "var(--accent)", color: "#05070d", borderColor: "transparent" },
  secondary: { background: "transparent", color: "var(--fg-1)", borderColor: "var(--line-2)" },
  ghost: { background: "transparent", color: "var(--fg-2)", borderColor: "transparent" },
  danger: { background: "transparent", color: "var(--danger)", borderColor: "var(--danger)" },
};

const sizes: Record<ButtonSize, React.CSSProperties> = {
  sm: { padding: "6px 12px", fontSize: "var(--text-sm)" },
  md: { padding: "9px 16px" },
  lg: { padding: "12px 22px", fontSize: "var(--text-md)" },
};

export function Button({
  variant = "primary",
  size = "md",
  disabled,
  pending,
  pendingLabel = "Working...",
  icon,
  children,
  style,
  ...rest
}: ButtonProps) {
  const [hover, setHover] = useState(false);
  const unavailable = disabled || pending;
  const hoverStyle: React.CSSProperties =
    hover && !unavailable
      ? variant === "primary"
        ? { background: "var(--accent-strong)" }
        : variant === "danger"
          ? { background: "var(--danger-dim)" }
          : { background: "var(--bg-3)", color: "var(--fg-1)" }
      : {};
  return (
    <button
      type="button"
      disabled={unavailable}
      aria-busy={pending || undefined}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        ...base,
        ...variants[variant],
        ...sizes[size],
        ...(unavailable ? { opacity: 0.4, cursor: "default" } : {}),
        ...hoverStyle,
        ...style,
        ...(pending ? { transition: "none" } : {}),
      }}
      {...rest}
    >
      {icon}
      {pending === undefined ? (
        children
      ) : (
        <span style={{ display: "grid" }}>
          <span
            aria-hidden={pending || undefined}
            style={{ gridArea: "1 / 1", visibility: pending ? "hidden" : "visible" }}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending || undefined}
            style={{ gridArea: "1 / 1", visibility: pending ? "visible" : "hidden" }}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </button>
  );
}

