/**
 * The Subscriptions "Models" section, run against the REAL catalog path -
 * no FM3000_QUOTA_FIXTURE_DIR. That fixture substitutes a hand-authored
 * two-model catalog for the whole fetcher, which is exactly why the section
 * could list providers the user had never signed in to without any test
 * noticing: piAuth.catalogModels() and buildModelsCatalog() never ran e2e.
 *
 * Here they do. Claude and Cursor are signed in through their stand-in
 * clients; Grok has an account but it is switched off; Codex, Copilot and
 * Kimi were never connected at all. Only the first two may appear.
 *
 * Nothing in this test reaches the network: the enabled Claude account
 * resolves no usage credential - its stand-in store has no credentials file
 * and no Keychain item exists for a throwaway config root - so the sensor
 * reports auth_required without any HTTP; Grok is disabled; Cursor's usage
 * RPC is pointed at a local stub (`FM3000_CURSOR_USAGE_URL`) so CD-4=B2
 * cannot phone api2.cursor.sh. The model catalog comes from pi-ai's bundled
 * data (launch.ts sets PI_OFFLINE).
 */

const GROK_DISABLED = "acct_grok_off";
const CLAUDE_PERSONAL = "acct_claude1";
const CURSOR_PERSONAL = "acct_cursor1";

function seedAccounts(userDataDir: string): void {
  const accountsDir = join(userDataDir, "accounts");
  const grokDir = join(accountsDir, "xai", GROK_DISABLED);
  mkdirSync(grokDir, { recursive: true, mode: 0o700 });
  writeFileSync(
    join(grokDir, "auth.json"),
    JSON.stringify({ xai: { type: "api_key", key: "x" } }),
    {
      mode: 0o600,
    },
  );
  mkdirSync(join(accountsDir, "anthropic-claude", CLAUDE_PERSONAL), {
    recursive: true,
    mode: 0o700,
  });
  seedSignedInCursorStore(join(accountsDir, "cursor", CURSOR_PERSONAL));
  writeFileSync(
    join(accountsDir, "registry.json"),
    JSON.stringify({
      version: 1,
      accounts: [
        {
          id: GROK_DISABLED,
          providerId: "xai",
          kind: "api_key",
          label: "Personal",
          // Signed in, but switched off: it leaves the selection pool, so it
          // leaves this section too.
          enabled: false,
          createdAt: Date.parse("2026-08-01T00:00:00Z"),
        },
        {
          id: CLAUDE_PERSONAL,
          providerId: "anthropic-claude",
          kind: "subscription_oauth",
          label: "Personal Max",
          enabled: true,
          createdAt: Date.parse("2026-08-02T00:00:00Z"),
        },
        {
          id: CURSOR_PERSONAL,
          providerId: "cursor",
          kind: "subscription_oauth",
          label: "Personal Pro",
          enabled: true,
          createdAt: Date.parse("2026-08-03T00:00:00Z"),
        },
      ],
      pins: {},
    }),
    { mode: 0o600 },
  );
}

let launched: LaunchedApp;
let cursorUsage: StubCursorUsage;

test.beforeAll(async () => {
  const userDataDir = mkdtempSync(join(tmpdir(), "fm3000-e2e-"));
  seedAccounts(userDataDir);
  cursorUsage = await startStubCursorUsage({ accept: ["stub"] });
  launched = await launchApp({
    withMockProvider: true,
    userDataDir,
    prepareHome: (homeDir) => seedSignedInClaudeStore(claudeDefaultStore(homeDir)),
    env: {
      FM3000_CLAUDE_CLI: writeMockClaudeClient(mkdtempSync(join(tmpdir(), "fm3000-claude-stub-"))),
      FM3000_CURSOR_CLI: writeMockCursorClient(mkdtempSync(join(tmpdir(), "fm3000-cursor-stub-"))),
      FM3000_CURSOR_USAGE_URL: cursorUsage.url,
    },
  });
  await launched.page.getByRole("button", { name: "Settings" }).click();
  await launched.page.getByRole("tab", { name: "Subscriptions" }).click();
});

test.afterAll(async () => {
  await launched.close();
  await closeStubCursorUsage(cursorUsage);
});

