  await high.getByRole("button", { name: "Composer 2.5", exact: true }).click();

  await expect(high.getByRole("button", { name: "Composer 2.5", exact: true })).toBeVisible();
  await expect(
    models
      .locator('[data-slot-group="off"]')
      .getByRole("button", { name: "Composer 2.5", exact: true }),
